describe('Accessible Product Images and Login Fields', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should have accessible attributes on login fields and product images', () => {
    // Verify login fields have non-empty placeholder attributes
    cy.get('[data-testid="username"]').should('have.attr', 'placeholder', 'Username');
    cy.get('[data-testid="password"]').should('have.attr', 'placeholder', 'Password');

    // Verify login button is visible and has accessible attributes
    cy.get('[data-testid="login-button"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('have.attr', 'aria-label', 'Login');

    // Verify product images have non-empty alt attributes
    cy.get('[data-testid="inventory-item"]').each(($item) => {
      cy.wrap($item).should('have.attr', 'alt');
    });

    // Verify at least one product image has a descriptive alt attribute
    cy.get('[data-testid="inventory-item-img-link"]').first().then((img) => {
      cy.wrap(img).should('have.attr', 'alt', 'Product image');
    });

    // Verify login form is visible and accessible
    cy.get('[data-testid="login-credentials-container"]').should('be.visible');
    cy.get('[data-testid="login-credentials"]').should('have.attr', 'aria-label', 'Login credentials');
  });

  it('should handle login with standard_user and display accessible product images after login', () => {
    // Intercept login API call
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 200,
      body: {
        token: 'valid-token',
        user: {
          id: 1,
          username: 'standard_user',
          email: 'standard_user@example.com'
        }
      }
    }).as('loginSuccess');

    // Fill login form with valid credentials
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for login API call to complete
    cy.wait('@loginSuccess');

    // Verify login was successful and user is redirected
    cy.url().should('include', '/dashboard');

    // Verify product images still have accessible attributes after login
    cy.get('[data-testid="inventory-item"]').each(($item) => {
      cy.wrap($item).should('have.attr', 'alt');
    });

    // Verify login form is no longer visible
    cy.get('[data-testid="login-credentials-container"]').should('not.exist');
  });
});
